### 3. `app/LoginHelper.java`

Ajuda a validar login sem jogar exceções direto para a interface gráfica.

```java
package app;

import util.LoginValidator;
import business.control.UserManager;
import business.control.LoginInvalidException;
import infra.InfraException;
import javax.swing.JOptionPane;

/**
 * Realiza a validação de credenciais de forma amigável para a UI.
 */
public class LoginHelper {

    private final LoginValidator validator;

    public LoginHelper() {
        this.validator = new LoginValidator();
    }

    public CredencialValida validarCredenciais() {
        String email = pedirEmail();
        if (email == null || email.trim().isEmpty()) {
            return null;
        }

        String senha = pedirSenha();
        if (senha == null || senha.trim().isEmpty()) {
            return null;
        }

        try {
            boolean valido = validator.checkUserLogin(email, senha);
            if (!valido) {
                return new CredencialValida(email, "E-mail ou senha incorretos.");
            }
            return new CredencialValida(email, null);
        } catch (LoginInvalidException e) {
            return new CredencialValida(email, e.getMessage());
        } catch (Exception e) {
            return new CredencialValida(email, "Erro interno ao verificar as credenciais: " + e.getMessage());
        }
    }

    private String pedirEmail() {
        String entrada = JOptionPane.showInputDialog(
                null, "E-mail do usuário:", "Entrar",
                javax.swing.JOptionPane.getWarningIcon());
        if (entrada == null || entrada.trim().isEmpty()) {
            return null;
        }
        return entrada;
    }

    private String pedirSenha() {
        Object dialog = JOptionPane.showPasswordDialog(
                null, "Senha do usuário:", "Entrar",
                javax.swing.WARNING_MESSAGE);
        if (dialog == null) {
            return null;
        }
        if (dialog instanceof String) {
            String s = (String) dialog;
            if (s.trim().isEmpty()) {
                return null;
            }
            return s;
        }
        return null;
    }
}
```

