    private void carregarListaCursos() throws Exception {
        List<Map.Entry<String, Curso>> entradas = lerMapCursos();
        String[][] headers = {"Nome", "Cidade", "Centro"};
        String[][] dados = entradas.isEmpty() ? null : gerarDadosCursos(entradas);

        if (dados == null || dados.length == 0) {
            tabelaCursos = new JTable(0, 3, null);
        } else {
            int tamanho = entradas.size() + 1;
            String[][] arr = new String[tamanho][3];
            for (int i = 0; i < entradas.size(); i++) {
                Map.Entry<String, Curso> e = entradas.get(i);
                Curso c = e.getValue();
                arr[i + 1][0] = c.getNome();
                arr[i + 1][1] = c.getCidade();
                arr[i + 1][2] = c.getCentro();
            }
            tabelaCursos = new JTable(arr, headers);
            tabelaCursos.setAutoCreateRowSize(true);
            tabelaCursos.setSelectedRowCount(0);
        }

        tabelaCursos.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
        scrollCursos = new JScrollPane(tabelaCursos);
        limparCamposCursos();
    }

    private List<Map.Entry<String, Curso>> lerMapCursos() throws InfraException {
        Map<String, Curso> mapa = cursoManager.getCursos();
        if (mapa == null) {
            return new ArrayList<>();
        }
        ArrayList<Map.Entry<String, Curso>> lista = new ArrayList<>();
        Iterator<Map.Entry<String, Curso>> iter = mapa.entrySet().iterator();
        while (iter.hasNext()) {
            lista.add(iter.next());
        }
        return lista;
    }

