    private void adicionarCurso() {
        String nome = tfNomeCurso.getText().trim();
        String cidade = tfCidadeCurso.getText().trim();
        String centro = tfCentroCurso.getText().trim();

        if (nome.isEmpty() || cidade.isEmpty() || centro.isEmpty()) {
            lblStatus.setText("Preencha Nome, Cidade e Centro.");
            return;
        }

        Map<String, Curso> mapaCursos = null;
        try {
            mapaCursos = cursoManager.getCursos();
        } catch (Exception e) {
            // erro já tratado no try/catch abaixo
        }

        if (mapaCursos != null && mapaCursos.keySet().contains(nome)) {
            int escolha = JOptionPane.showConfirmDialog(
                    null, "Já existe um curso com o nome \"" + nome + "\". Deseja substituir?",
                    "Atenção", JOptionPane.YESNO_OPTION);
            if (escolha != JOptionPane.YES_OPTION) {
                return;
            }
        }

        try {
            String[] parametros = {nome, cidade, centro};
            cursoManager.adicionarCurso(parametros);
            lblStatus.setText("Curso \"" + nome + "\" adicionado com sucesso.");
            carregarListaCursos();
        } catch (Exception e) {
            lblStatus.setText("Erro ao adicionar curso: " + e.getMessage());
        }
    }

    private void removerCursoSelecionado() {
        int linha = tabelaCursos.getSelectedRow();
        if (linha < 0) {
            lblStatus.setText("Nenhuma linha selecionada.");
            return;
        }

        String nome = tabelaCursos.getValueAt(linha, 0).toString();
        int escolha = JOptionPane.showConfirmDialog(
                null, "Remover o curso \"" + nome + "\" da gestão?",
                "Confirmar remoção", JOptionPane.YESNO_OPTION);

        if (escolha == JOptionPane.CANCELLED) {
            return;
        }

        try {
            cursoManager.removerCurso(nome);
            lblStatus.setText("Curso removido com sucesso.");
            carregarListaCursos();
        } catch (IllegalArgumentException e) {
            lblStatus.setText("Curso não encontrado para remoção: " + e.getMessage());
        } catch (Exception e) {
            lblStatus.setText("Erro ao remover curso: " + e.getMessage());
        }
    }

    private void renovarCursos() {
        try {
            carregarListaCursos();
        } catch (Exception e) {
            lblStatus.setText("Erro ao renovar a lista de cursos: " + e.getMessage());
        }
