package app;

import java.io.FileInputStream;
import java.io.IOException;
import java.util.Properties;

/**
 * Carrega as credenciais do administrador a partir de um arquivo de propriedades.
 * Se o arquivo não existir, utiliza valores de fallback.
 */
public class ConfiguracaoAdmin {

    private static final String ARQUIVO_PROPRIEDADES = "PropriedadesAdmin.properties";
    private static final String FALBACK_EMAIL = "admin@admin.com";
    private static final String FALBACK_SENHA = "abracadabra";

    private static Properties props = null;

    /**
     * Carrega as configurações uma única vez (thread-safe).
     */
    public static synchronized void carregar() throws IOException {
        if (props != null && !props.isEmpty()) return;
        try (FileInputStream fis = new FileInputStream(ARQUIVO_PROPRIEDADES)) {
            props = new Properties();
            props.load(fis);
        } catch (IOException ex) {
            System.err.println("Não foi possível carregar " + ARQUIVO_PROPRIEDADES + ". Usando credenciais de fallback.");
            fallback();
        }
    }

    private static void fallback() {
        // Não recomendado usar isso em produção; apenas durante desenvolvimento.
        System.out.println("Falta de arquivo de configuração. Fallback para admin@admin.com / abracadabra.");
        props = new Properties();
        props.setProperty("admin.email", FALBACK_EMAIL);
        props.setProperty("admin.senha", FALBACK_SENHA);
    }

    public static String getEmail() {
        try { carregar(); } catch (IOException e) {}
        return props != null ? props.getProperty("admin.email") : FALBACK_EMAIL;
    }

    public static String getSenha() {
        try { carregar(); } catch (IOException e) {}
        return props != null ? props.getProperty("admin.senha") : FALBACK_SENHA;
    }

    public static boolean isEmailAdmin(String email) {
        try { carregar(); } catch (IOException e) {}
        String expected = getEmail().toLowerCase().trim();
        String input = ((email != null) ? email.toString() : "").toLowerCase().trim();
        return expected.equals(input);
    }
}
```
