package app;

import business.control.UserManager;
import util.LoginValidator;
import util.LoginInvalidException;
import infra.InfraException;
import javax.swing.JOptionPane;

/**
 * Auxilia na autenticação de usuários.
 * Não deve ser confundido com verificação de perfil de administrador.
 */
public class LoginHelper {

    private final UserManager userManager;
    private final LoginValidator validator;

    public LoginHelper() {
        this.userManager = new UserManager();
        this.validator = new LoginValidator();
    }

    /**
     * Solicita e-mail e senha e verifica os credenciais.
     * Retorna o e-mail válido caso seja bem-sucedido, ou lança InfraException.
     */
    public String autenticar(String email, String senha) throws InfraException {
        try {
            if (email == null || email.trim().isEmpty() || senha == null || senha.trim().isEmpty()) {
                throw new LoginInvalidException("E-mail e senha são obrigatórios.");
            }
            boolean valido = validator.checkUserLogin(email, senha);
            if (!valido) {
                throw new LoginInvalidException("E-mail ou senha incorretos. Por favor, tente novamente.");
            }
            return email;
        } catch (LoginInvalidException e) {
            throw new InfraException("Autenticação falhou: " + e.getMessage());
        } catch (Exception e) {
            throw new InfraException("Erro inesperado na autenticação: " + e.getMessage());
        }
    }

    /**
     * Interfaz simples para solicitar dados de login em uma janela existente.
     */
    public String pedirDadosJanela(JWindow janela) {
        String email = JOptionPane.showInputDialog(janela, "E-mail do usuário:", "Entrar",
                JOptionPane.get-warningIcon());
        if (email == null || email.trim().isEmpty()) return null;
        String senha = JOptionPane.showPasswordDialog(janela,
                "Digite a senha para continuar.",
                "Entrar",
                JOptionPane.WARNING_MESSAGE,
                null,
                null,
                null);
        if (senha == null) return null;
        return email;
    }
}
