    public void run() {
        try {
            configuracao.carregar();
            iniciarMenuPrincipal();
        } catch (Exception e) {
            JOptionPane.showMessageDialog(null, "Falha grave ao iniciar o sistema:\n" + e.getMessage(),
                    "Erro crítico", JOptionPane.ERROR_MESSAGE);
            e.printStackTrace();
            System.exit(1);
        }
