    private void iniciarMenuPrincipal() {
        while (true) {
            String modo = (configuracao.isEmailAdmin(getEmailAutenticado())) ? "ADMINISTRADOR" : "USUÁRIO";
            StringBuilder msg = new StringBuilder("=== SouUFPB — Modo: " + modo);
            msg.append("\nEscolha a opção desejada:");
            msg.append("\n1-Cadastrar usuário\n2-Entrar\n3-Acessar área administrativa\n4-Sair");
            String opcao = JOptionPane.showInputDialog(msg.toString(), "SouUFPB", null);

            if (opcao == null) {
                break;
            }

            try {
                int escolha = Integer.parseInt(opcao.trim());
                switch (escolha) {
                    case 1:
                        cadastrarUsuario();
                        continue;
                    case 2:
                        fazEntrada();
                        break;
                    case 3:
                        acessarAdministrativo();
                        continue; // continua loop para voltar ao menu principal após abrir painel
                    case 4:
                        System.exit(0);
                    default:
                        JOptionPane.showMessageDialog(null, "Opção inválida!");
                }
            } catch (NumberFormatException e) {
                JOptionPane.showMessageDialog(null, "Digite apenas números inteiros.");
            }
        }
