        } catch (Exception e) {
            JOptionPane.showMessageDialog(null, "Falha ao abrir o painel administrativo: " + e.getMessage());
            e.printStackTrace();
        }
    }

    private void mostrarMenuNormal(String email) {
        while (true) {
            String opcao = JOptionPane.showInputDialog(
