public class SouUFPBApp {

    private final ConfiguracaoAdmin configuracao;
    private final LoginHelper loginHelper;

    public SouUFPBApp() {
        this.configuracao = new ConfiguracaoAdmin();
        this.loginHelper = new LoginHelper();
    }

    public void run() {
        try {
            configuracao.carregar();
            iniciarMenuPrincipal();
        } catch (Exception e) {
            JOptionPane.showMessageDialog(null, "Falha crítica ao iniciar o sistema:\n" + e.getMessage(),
                    "Erro", JOptionPane.ERROR_MESSAGE);
            e.printStackTrace();
            System.exit(1);
        }
    }

    private void iniciarMenuPrincipal() {
        while (true) {
            String ehAdmin = configuracao.isEmailAdmin(getEmailAtual()) ? "ADMINISTRADOR" : "USUÁRIO COMUM";
            String mensagem = "=== SouUFPB — Modo: " + ehAdmin;
            mensagem += "\n\nEscolha a opção desejada:";
            mensagem += "\n1 - Cadastrar usuário\n2 - Entrar\n3 - Acessar área administrativa\n4 - Sair";

            String opcao = JOptionPane.showInputDialog(mensagem, "SouUFPB", null);

            if (opcao == null) {
                break; // encerra a aplicação
            }

            try {
                int escolha = Integer.parseInt(opcao.trim());
                switch (escolha) {
                    case 1:
                        cadastrarUsuario();
                        continue;
                    case 2:
                        processarEntrada();
                        break;
                    case 3:
                        acessarAreaAdministrativa();
                        continue; // volta ao menu principal depois de abrir o painel
                    case 4:
                        System.exit(0);
                    default:
                        JOptionPane.showMessageDialog(null, "Opção inválida!");
                }
            } catch (NumberFormatException e) {
                JOptionPane.showMessageDialog(null, "Digite apenas um número inteiro.");
            }
        }
    }

    private StringgetEmailAtual() {
        CredencialValida cred = loginHelper.validarCredenciais();
        return (cred != null && cred.isValida()) ? cred.getEmail() : null;
    }

    private void processarEntrada() {
        CredencialValida cred = loginHelper.validarCredenciais();
        if (cred == null || !cred.isValida()) {
            return;
        }
        String email = cred.getEmail();
        try {
            if (configuracao.isEmailAdmin(email.toLowerCase().trim())) {
                acessarAreaAdministrativa();
            } else {
                mostrarMenuNormal(email);
            }
        } catch (Exception e) {
            JOptionPane.showMessageDialog(null, "Erro ao tratar a entrada: " + e.getMessage());
        }
    }

    private void acessarAreaAdministrativa() {
        String email = getEmailAtual();
        if (email == null) return;
        if (!configuracao.isEmailAdmin(email.toLowerCase().trim())) {
            JOptionPane.showMessageDialog(null, "Acesso negado!\nAs credenciais de administrador informadas estão inválidas.");
            return;
        }
        try {
            new SouUFPBAdmin(email).setVisible(true);
        } catch (Exception e) {
            JOptionPane.showMessageDialog(null, "Falha ao abrir a área administrativa:\n" + e.getMessage());
            e.printStackTrace();
        }
    }

    private void mostrarMenuNormal(String email) {
        while (true) {
            String opcao = JOptionPane.showInputDialog(
                    "Olá, " + email + ".\nEscolha a opção desejada:\n" +
                    "1 - Ver os Cursos da UFPB\n2 - Fazer teste vocacional\n3 - Sair",
                    "SouUFPB", null);

            if (opcao == null) {
                break;
            }
            try {
                int escolha = Integer.parseInt(opcao.trim());
                switch (escolha) {
                    case 1:
                        Cursos.entraremcursos();
                        break;
                    case 2:
                        Testes.questionario(email);
                        break;
                    case 3:
                        System.exit(0);
                    default:
                        JOptionPane.showMessageDialog(null, "Opção inválida!");
                }
            } catch (NumberFormatException | Exception e) {
                JOptionPane.showMessageDialog(null, "Informe apenas um número válido.\n" + (e != null ? e.getMessage() : ""),
                        "Entrada inválida", JOptionPane.WARNING_MESSAGE);
            }
        }
    }

    private void cadastrarUsuario() {
        String nome = pedirTexto("Nome do usuário:");
        if (nome == null || nome.trim().isEmpty()) return;

        String email = pedirTexto("E-mail do usuário:");
        if (email == null || email.trim().isEmpty()) return;

        String senha = pedirSenha("Senha do usuário:");
        if (senha == null || senha.trim().isEmpty()) return;

        String[] args = {nome.trim(), email.trim(), senha.trim()};
        try {
            UserManager userManager = new UserManager();
            userManager.addUser(args);
            JOptionPane.showMessageDialog(null, "Usuário cadastrado com sucesso!");
        } catch (Exception e) {
            JOptionPane.showMessageDialog(null, "Erro ao cadastrar usuário:\n" + e.getMessage());
        }
    }

    // --------------------------------------------------------- helpers UI
    private String pedirTexto(String pergunta) {
        return JOptionPane.showInputDialog(null, pergunta, "SouUFPB",
                javax.swing.JOptionPane.getWarningIcon());
    }

    private String pedirSenha(String pergunta) {
        Object dialog = javax.swing.JOptionPane.showPasswordDialog(
                null, pergunta, "SouUFPB", javax.swing.WARNING_MESSAGE);
        if (dialog == null) return null;
        if (dialog instanceof String) {
            String s = (String) dialog;
            if (s.trim().isEmpty()) return null;
            return s;
        }
        return null;
    }
}
