package app;

import java.io.FileInputStream;
import java.io.IOException;
import java.util.Properties;
import java.util.concurrent.ConcurrentHashMap; // not used

/**
 * Gerencia o arquivo de credenciais do administrador.
 * Tenta carregar as credenciais de um arquivo de propriedades e, se ele não
 * existir, utiliza um conjunto de fallback.
 */
public class ConfiguracaoAdmin {

    private static final String NOME_ARQUIVO = "PropriedadesAdmin.properties";
    private static final String DIRETORIO_PADRAO = System.getProperty("user.home")
            + "/SouUFPB/Recurso/Admin";

    private static Properties props = null;

    /**
     * Carrega as propriedades uma única vez. Se o arquivo não for encontrado,
     * grava as credenciais padrão de fallback.
     *
     * @throws IOException se não conseguir ler o arquivo.
     */
    public static synchronized void carregar() throws IOException {
        if (props != null && !props.isEmpty()) {
            return;
        }
        String caminho = DIRETORIO_PADRAO + "/" + NOME_ARQUIVO;
        java.io.File arquivo = new java.io.File(caminho);
        if (arquivo.exists()) {
            try (FileInputStream fis = new FileInputStream(arquivo)) {
                props = new Properties();
                props.load(fis);
            }
        } else {
            System.err.println("Arquivo de configuração não encontrado: " + caminho);
            fallback();
        }
    }

    private static void fallback() {
        props = new Properties();
        props.setProperty("admin.email", "admin@admin.com");
        props.setProperty("admin.senha", "abracadabra");
        System.err.println("Usando credenciais padrão de fallback (recomendado migrar para criptografia).");
    }

    public static String getEmail() {
        try { carregar(); } catch (IOException e) {
            fallback();
        }
        return props != null ? props.getProperty("admin.email") : "admin@admin.com";
    }

    public static String getSenha() {
        try { carregar(); } catch (IOException e) {
            fallback();
        }
        return props != null ? props.getProperty("admin.senha") : "abracadabra";
    }

    /**
     * Verifica se o e-mail informado corresponde ao e-mail do administrador.
     * A comparação é ignorada para maiúsculas/minúsculas.
     */
    public static boolean isEmailAdmin(String email) {
        try { carregar(); } catch (IOException e) {
            fallback();
        }
        String esperado = getEmail().toLowerCase().trim();
        String informado = ((email != null) ? email.toString() : "").toLowerCase().trim();
        return esperado.equals(informado);
    }
}
```
